<?php
// Isolated SQLite regression: an author autosave must not discard a long model draft.
declare(strict_types=1);
require __DIR__.'/run.php';
$db=openDatabase(['dsn'=>'sqlite::memory:']);
$db->exec('CREATE TABLE workspace(id INTEGER PRIMARY KEY,version INTEGER,payload TEXT)');
$db->exec('CREATE TABLE operations(operation_id TEXT PRIMARY KEY,payload_hash TEXT,result_version INTEGER)');
$state=$s;$blocks=[];
for($i=1;$i<=1000;$i++)$blocks[]=['id'=>$i===1?$pid:uuid(),'label'=>$i,'text'=>'রহস্যের নতুন সূত্র। '.str_repeat('অন্ধকার পথে তারা এগিয়ে গেল। ',10),'section'=>''];
$state['revisions'][0]['paragraphs']=$blocks;
$latest=$state['revisions'][0];$latest['id']=uuid();$latest['parentId']=$rid;$latest['paragraphs'][999]['text']='Author ending';
$state['revisions'][]=$latest;$state['chapters'][0]['headId']=$latest['id'];$state['chapters'][0]['approvedId']=$rid;
$q=$db->prepare('INSERT INTO workspace VALUES(1,1,?)');$q->execute([json_encode($state)]);
$args=['operation_id'=>uuid(),'chapter_id'=>$cid,'base_revision_id'=>$rid,'title'=>'Large rewrite','rationale'=>'Opening only','paragraphs'=>$blocks];$args['paragraphs'][0]['text']='Proposed opening';
$result=callTool($db,'save_proposal',$args);$saved=loadWorkspace($db);
check($result['saved']&&$result['stale']&&$result['baseRevisionId']===$rid&&$result['currentRevisionId']===$latest['id'],'Large proposal survives an intervening author autosave and reports exact source');
check($saved['state']['proposals'][0]['paragraphs']===$args['paragraphs']&&$saved['state']['proposals'][0]['baseRevisionId']===$rid,'Entire draft stored unchanged against its original source');
check($saved['state']['chapters']===$state['chapters']&&$saved['state']['revisions']===$state['revisions'],'Newer author prose, history and approved revision remain unchanged');
check(callTool($db,'read_proposal',['chapter_id'=>$cid,'proposal_id'=>$result['id']])['stale'],'Existing proposal read reports newer manuscript head');
check(callTool($db,'save_proposal',$args)['duplicate']&&loadWorkspace($db)['version']===$saved['version'],'Retry does not create another large proposal');
$overlap=$args;$overlap['operation_id']=uuid();$overlap['paragraphs'][999]['text']='Conflicting proposed ending';
check(callTool($db,'save_proposal',$overlap)['stale'],'Overlapping changes may be stored for explicit author conflict review');
$fresh=$args;$fresh['operation_id']=uuid();$fresh['base_revision_id']=$latest['id'];$fresh['paragraphs']=$latest['paragraphs'];
check(!callTool($db,'save_proposal',$fresh)['stale'],'Current-head proposals retain normal behavior');
$version=loadWorkspace($db)['version'];
$bad=$args;$bad['operation_id']=uuid();$bad['base_revision_id']=uuid();rejects(fn()=>callTool($db,'save_proposal',$bad),409,'Unknown source rejected');
$bad['base_revision_id']='P1';rejects(fn()=>callTool($db,'save_proposal',$bad),422,'Paragraph label cannot masquerade as a source revision');
$bad=$args;$bad['operation_id']=uuid();$bad['paragraphs'][0]['id']=uuid();rejects(fn()=>callTool($db,'save_proposal',$bad),422,'Stable paragraph reference guard still rejects identity substitution');
$context=['operation_id'=>uuid(),'chapter_id'=>$cid,'revision_id'=>$rid,'summary'=>'Outdated','facts'=>[]];rejects(fn()=>callTool($db,'save_context',$context),409,'Context indexing still requires latest source');
check(loadWorkspace($db)['version']===$version,'Rejected requests make no workspace changes');
$changed=$args;$changed['title']='Different';rejects(fn()=>callTool($db,'save_proposal',$changed),409,'Operation IDs cannot be reused for changed prose');
$foreign=$latest;$foreign['id']=uuid();$foreign['chapterId']=uuid();$scratch=$state;$scratch['revisions'][]=$foreign;
rejects(fn()=>proposalSource($scratch,$latest,$foreign['id']),409,'Foreign chapter revision is not an eligible source');
$branch=$latest;$branch['id']=uuid();$branch['parentId']=$rid;$scratch=$state;$scratch['revisions'][]=$branch;
rejects(fn()=>proposalSource($scratch,$latest,$branch['id']),409,'Sibling branch is not an eligible source');
$renumbered=$latest;$renumbered['id']=uuid();$renumbered['parentId']=$latest['id'];$renumbered['edition']=2;$scratch=$state;$scratch['revisions'][]=$renumbered;
rejects(fn()=>proposalSource($scratch,$renumbered,$rid),409,'Previous reference edition requires fresh reconciliation');
check(proposalSource($scratch,$renumbered,$renumbered['id'])['id']===$renumbered['id'],'Current source remains valid after reference renumbering');
$loaded=loadWorkspace($db);$trash=$loaded['state'];$trash['chapters'][0]['deletedAt']=stamp();writeWorkspace($db,$trash,$loaded['version'],uuid(),'trash');
$bad=$args;$bad['operation_id']=uuid();rejects(fn()=>callTool($db,'save_proposal',$bad),409,'Trashed chapters remain protected');
check(callTool($db,'save_proposal',$args)['duplicate'],'Previously successful retry remains duplicate-safe after trashing');
echo "$count total proposal-source checks passed.\n";
